exempt = (input('exempt_assets') || {})['CKV_AWS_64'] || []

control 'CKV_AWS_64' do
  title 'Ensure all data stored in the Redshift cluster is securely encrypted at rest'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_redshift_cluster resources that actually exist, read through the
    stock inspec-aws aws_redshift_cluster resource.
  DESC

  desc 'rationale', <<~RATIONALE
    An unencrypted warehouse exposes every table it holds through the
    storage layer and through any snapshot.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_redshift_cluster: encrypted is True
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_redshift_cluster:

      resource "aws_redshift_cluster" "example" {
        encrypted  = true
        kms_key_id = aws_kms_key.redshift.arn
      }

    Out of band — aws_redshift_cluster:

      aws redshift modify-cluster --cluster-identifier <id> --encrypted --kms-key-id <key-arn>
  FIX

  tag checkov_id:            'CKV_AWS_64'
  tag checkov_category:      'ENCRYPTION'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_redshift_cluster]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/redshift_cluster#encrypted'
  tag nist:                  ['SC-28', 'SC-28 (1)']
